Widget ddIcon(DdIcon icon, {double size = 18, Color color = const Color(0xFF1F2329)}) {
  final fill = _fill[icon];
  final svg = fill != null
      ? '<svg xmlns="http://www.w3.org/2000/svg" viewBox="${fill.$1}" fill="#000">${fill.$2}</svg>'
      : '$_strokeHead${_stroke[icon]}</svg>';
  return SvgPicture.string(svg, width: size, height: size, colorFilter: ColorFilter.mode(color, BlendMode.srcIn));
}

